function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((done) => {
    resolve = done;
  });
  return { promise, resolve };
}

describe("engine comparison UI", () => {
  let container: HTMLDivElement;
  let root: Root;

  const button = (label: string) => {
    const found = Array.from(container.querySelectorAll("button")).find(
      (candidate) => candidate.textContent === label,
    );
    if (!found) throw new Error(`missing ${label} button`);
    return found;
  };

  const click = async (label: string) => {
    await act(async () => {
      button(label).dispatchEvent(new MouseEvent("click", { bubbles: true }));
    });
  };

  const expectComparison = (visible: boolean) => {
    expect(container.textContent?.includes("Cross-validation")).toBe(visible);
  };

  beforeEach(async () => {
    (globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
    ipc.fetchReferenceDesign.mockResolvedValue(reference);
    ipc.fetchMotors.mockResolvedValue([]);
    ipc.runSimulation.mockReset();
    ipc.runSpread.mockReset();

    // Stateful fake of the Rust document store: enough command semantics
    // for the UI flows under test (scalar edits, motor, coarse replace).
    let designNow: Design = reference;
    let past: Design[] = [];
    let future: Design[] = [];
    const state = () => ({
      vehicle: { name: designNow.name, parts: [] },
      design: designNow,
      studies: [],
      can_undo: past.length > 0,
      can_redo: future.length > 0,
    });
    ipc.getDocument.mockImplementation(async () => state());
    ipc.dispatchCommand.mockImplementation(
      async (cmd: { cmd: string } & Record<string, unknown>) => {
        past.push(designNow);
        future = [];
        if (cmd.cmd === "set_sim_param") {
          designNow = { ...designNow, [cmd.param as string]: cmd.value } as Design;
        } else if (cmd.cmd === "select_motor") {
          designNow = { ...designNow, motor_designation: cmd.designation as string };
        } else if (cmd.cmd === "set_design") {
          designNow = cmd.design as Design;
        }
        return state();
      },
    );
    ipc.undoDocument.mockImplementation(async () => {
      const prev = past.pop();
      if (prev) {
        future.push(designNow);
        designNow = prev;
      }
      return state();
    });
    ipc.redoDocument.mockImplementation(async () => {
      const next = future.pop();
      if (next) {
        past.push(designNow);
        designNow = next;
      }
      return state();
    });
    container = document.createElement("div");
    document.body.append(container);
    root = createRoot(container);
    await act(async () => {
      root.render(<App />);
      await Promise.resolve();
    });
  });

  afterEach(async () => {
    await act(async () => root.unmount());
    container.remove();
    vi.clearAllMocks();
  });

/* Ascent mission-control theme (v0.4 Step 10). Typography-first, dark,
   CSS custom properties only — no component framework. This file styles
   the workbench shell (header/tabs/content grid) and the command palette;
   existing panels keep their inline styles until the dedicated visual
   design pass (roadmap v0.5+) replaces the skin. */

:root {
  /* Surfaces, darkest to most elevated. */
  --ascent-bg: #0a0d12;
  --ascent-bg-elevated: #11151c;
  --ascent-bg-panel: #161b23;
  --ascent-border: #262d38;
  --ascent-border-strong: #384252;

  /* Text. */
  --ascent-text: #e6e8eb;
  --ascent-text-dim: #9aa1ab;
  --ascent-text-faint: #5b6472;

  /* Accent + status, reused from the existing state badge palette. */
  --ascent-accent: #58a6ff;
  --ascent-ok: #3fb950;
  --ascent-warn: #e8a33d;
  --ascent-danger: #c74b3c;

  /* Type. */
  --ascent-font-sans: system-ui, sans-serif;
  --ascent-font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  /* Spacing scale. */
  --ascent-space-1: 4px;
  --ascent-space-2: 8px;
  --ascent-space-3: 12px;
  --ascent-space-4: 16px;
  --ascent-space-5: 24px;

  --ascent-radius: 6px;
}

/* ---- Workbench shell ---------------------------------------------- */

.workbench {
  display: grid;
  grid-template-rows: auto auto auto 1fr;
  min-height: 100vh;
  background: var(--ascent-bg);
  color: var(--ascent-text);
  font-family: var(--ascent-font-sans);
}

.workbench-header {
  display: flex;
  align-items: center;
  gap: var(--ascent-space-4);
  padding: var(--ascent-space-3) var(--ascent-space-5);
  background: var(--ascent-bg-elevated);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ascent-text);
}

.workbench-toolbar {
  display: flex;
  align-items: center;
  gap: var(--ascent-space-2);
  margin-left: auto;
}

.workbench-tabs {
  display: flex;
  gap: var(--ascent-space-1);
  padding: 0 var(--ascent-space-5);
  background: var(--ascent-bg-elevated);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-tab {
  appearance: none;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--ascent-text-dim);
  font: inherit;
  font-size: 13px;
  letter-spacing: 0.02em;
  padding: var(--ascent-space-3) var(--ascent-space-2);
  cursor: pointer;
}

.workbench-tab:hover:not(:disabled) {
  color: var(--ascent-text);
}

.workbench-tab.active {
  color: var(--ascent-accent);
  border-bottom-color: var(--ascent-accent);
}

.workbench-tab:disabled {
  color: var(--ascent-text-faint);
  cursor: not-allowed;
}

.workbench-banner {
