//! They use `handle_line` directly: no process, model, or network is mocked.

use ascent_mcp::McpServer;
use serde_json::{json, Value};

fn call(server: &mut McpServer, id: u64, method: &str, params: Value) -> Value {
    server
        .handle_line(&json!({"jsonrpc":"2.0","id":id,"method":method,"params":params}).to_string())
        .expect("request must receive a response")
}

fn tool(server: &mut McpServer, id: u64, name: &str, arguments: Value) -> Value {
    call(server, id, "tools/call", json!({"name": name, "arguments": arguments}))["result"]["structuredContent"].clone()
}

fn seed_study(server: &mut McpServer) {
    tool(server, 1, "apply_proposal", json!({"lines":["create-study \"agent eval\" native 42 {\"kind\":\"dispersion\",\"flights\":5}"]}));
    tool(server, 2, "run_study", json!({"study_id": 1}));
}

#[test]
fn fin_widen_stales_verified_study_matches_golden() {
    let golden: Value = serde_json::from_str(include_str!("fixtures/evals/fin_widen_stales_verified_study.json")).unwrap();
    let mut server = McpServer::default();
    seed_study(&mut server);
    let proposal = tool(&mut server, 3, "propose_commands", json!({"lines":["set-part-param 3 span_m 0.05"]}));
    assert_eq!(proposal["diff"]["studies_made_stale"], golden["studies_made_stale"]);
    let state = tool(&mut server, 4, "apply_proposal", json!({"lines":["set-part-param 3 span_m 0.05"]}));
    assert_eq!(state["vehicle"]["parts"][1]["children"][0]["kind"]["span_m"], golden["span_m"]);
    // The agent re-runs the now-stale study through the Tasks shape, then
    // follows the fresh result into its evidence hash relation.
    let created = call(&mut server, 5, "tools/call", json!({"name":"run_study","arguments":{"study_id":1},"task":{}}));
    let task_id = created["result"]["task"]["taskId"].as_str().unwrap();
    let task = call(&mut server, 6, "tasks/result", json!({"taskId":task_id}));
    assert_eq!(task["result"]["structuredContent"]["studies"][0]["results"]["input_hash"].as_str().unwrap().len(), golden["hash_length"]);
    let evidence = tool(&mut server, 7, "read_evidence", json!({"study_id":1}));
    assert_eq!(evidence["links"][0]["relation"], golden["relation"]);
}

#[test]
fn invalid_batch_is_atomic_then_agent_recovers_matches_golden() {
    let golden: Value = serde_json::from_str(include_str!("fixtures/evals/invalid_batch_is_atomic_then_agent_recovers.json")).unwrap();
    let mut server = McpServer::default();
    let before = tool(&mut server, 1, "get_document", json!({}));
    let rejected = call(&mut server, 2, "tools/call", json!({"name":"apply_proposal","arguments":{"lines":["set-part-param 999 span_m 0.06"]}}));
    assert!(rejected["result"]["content"][0]["text"].as_str().unwrap().contains(golden["error_contains"].as_str().unwrap()));
    assert_eq!(tool(&mut server, 3, "get_document", json!({})), before);
    let after = tool(&mut server, 4, "apply_proposal", json!({"lines":["set-part-param 3 span_m 0.05"]}));
    assert_eq!(after["vehicle"]["parts"][1]["children"][0]["kind"]["span_m"], golden["span_m"]);
}

