### Client Component: useActionState with Server Action Prop

Source: https://github.com/react/react/blob/main/fixtures/flight/src/Counter.js

A 'use client' component demonstrating the React 19 pattern for connecting a server action to a form via useActionState. The server action (`incrementAction`) is passed as a prop from a server component, establishing the client/server boundary. useActionState provides the current state and a form-compatible dispatch. No useEffect or manual derived state needed.

```javascript
'use client';

import * as React from 'react';

import Container from './Container.js';

export function Counter({incrementAction}) {
  const [count, incrementFormAction] = React.useActionState(incrementAction, 0);
  return (
    <Container>
      <form>
        <button formAction={incrementFormAction}>Count: {count}</button>
      </form>
    </Container>
  );
}
```

--------------------------------

### React 19 useEffectEvent: avoid synchronous setState inside Effect body

Source: https://github.com/react/react/blob/main/compiler/packages/babel-plugin-react-compiler/src/__tests__/fixtures/compiler/valid-setState-in-useEffect-via-useEffectEvent-with-ref.expect.md

React 19's `useEffectEvent` extracts state updates (and side-effect logic) from the effect body, avoiding calls to setState synchronously within the effect which can trigger cascading re-renders. The `useEffectEvent` callback always has access to the latest props and state, and must NOT be included in the dependency array. This pattern is specifically validated by the React Compiler's `@validateNoSetStateInEffects` rule.

```javascript
import {useState, useRef, useEffect, useEffectEvent} from 'react';

function Component({x, y}) {
  const previousXRef = useRef(null);
  const previousYRef = useRef(null);

  const [data, setData] = useState(null);

  const effectEvent = useEffectEvent(() => {
    const data = load({x, y});
    setData(data);
  });

  useEffect(() => {
    const previousX = previousXRef.current;
    previousXRef.current = x;
    const previousY = previousYRef.current;
    previousYRef.current = y;
    if (!areEqual(x, previousX) || !areEqual(y, previousY)) {
      effectEvent();
    }
  }, [x, y]);

  return data;
}
```

--------------------------------

### Client Component: useFormStatus Pending Indicator + ErrorBoundary

Source: https://github.com/react/react/blob/main/fixtures/flight/src/Form.js

A 'use client' form component showing accessible pending feedback via useFormStatus() (no effect, no manual isPending state) and ErrorBoundary wrapping for error handling. The Status child reads `{pending}` from useFormStatus to display 'Saving...' while the action is in flight — this is the canonical pattern for form submission feedback without derived state or effects.

```javascript
'use client';

import * as React from 'react';
import {useFormStatus} from 'react-dom';
import ErrorBoundary from './ErrorBoundary.js';

function Status() {
  const {pending} = useFormStatus();
  return pending ? 'Saving...' : null;
}

export default function Form({action, children}) {
  const [isPending, setIsPending] = React.useState(false);

  return (
    <ErrorBoundary>
      <form action={action}>
        <label>
          Name: <input name="name" />
        </label>
        <label>
          File: <input type="file" name="file" />
        </label>
        <button>Say Hi</button>
        <Status />
      </form>
    </ErrorBoundary>
  );
}
```

--------------------------------

### Canonical async data fetching in useEffect with ignore flag for race conditions

Source: https://github.com/react/react/blob/main/packages/eslint-plugin-react-hooks/__tests__/ESLintRuleExhaustiveDeps-test.js

This is the React-recommended pattern for fetching data inside useEffect. The effect callback is synchronous (not async). An inner async function handles the fetch. A `let ignore = false` flag prevents setting state with stale results from a previous effect invocation when the dependency changes before the async operation completes. The dependency array `[query]` includes the reactive value used inside the effect.

```javascript
useEffect(() => {
  let ignore = false;
  fetchSomething();
  async function fetchSomething() {
    const result = await (await fetch('http://hn.algolia.com/api/v1/search?query=' + query)).json();
    if (!ignore) setState(result);
  }
  return () => { ignore = true; };
}, [query]);
```

--------------------------------

### useActionState with Permalink for URL-Backed Form State

Source: https://github.com/react/react/blob/main/packages/react-server-dom-webpack/src/__tests__/ReactFlightDOMForm-test.js

Demonstrates the React 19 permalink argument to useActionState, which sets the form's action URL to a specific path and enables state persistence across MPA-style page navigations. This is the official pattern for URL-backed filters/worklists: `useActionState(action, initialState, '/permalink')`. Also shows isPending feedback ('Pending...') and state display — all without effects or manual derived state.

```javascript
function Client({action}) {
  const [state, dispatch, isPending] = useActionState(
    action,
    initialState,
    '/permalink',
  );
  return (
    <form action={dispatch}>
      <span>{isPending ? 'Pending...' : ''}</span>
      <span>Count: {state.count}</span>
    </form>
  );
}
```

### open<T>(options): Promise<OpenDialogReturn<T>>

Source: https://v2.tauri.app/reference/javascript/dialog

Open a file/directory selection dialog. The selected paths are added to the filesystem and asset protocol scopes. When security is more important than the easy of use of this API, prefer writing a dedicated command instead. Note that the scope change is not persisted, so the values are cleared when the application is restarted. You can save it to the filesystem using tauri-plugin-persisted-scope.

```APIDOC
## open<T>(options): Promise<OpenDialogReturn<T>>

### Description
Open a file/directory selection dialog.

### Function Signature
```typescript
function open<T>(options): Promise<OpenDialogReturn<T>>
```

### Type Parameters
- `T` _extends_ `OpenDialogOptions`

### Parameters
- **options** (T) - Required

### Returns
`Promise<OpenDialogReturn<T>>` - A promise resolving to the selected path(s)

### Usage Example
```javascript
import { open } from '@tauri-apps/plugin-dialog';
// Open a selection dialog for image files
const selected = await open({
  multiple: true,
  filters: [{
    name: 'Image',
    extensions: ['png', 'jpeg']
  }]
});
if (Array.isArray(selected)) {
  // user selected multiple files
} else if (selected === null) {
  // user cancelled the selection
} else {
  // user selected a single file
}
```

```javascript
import { open } from '@tauri-apps/plugin-dialog';
import { appDir } from '@tauri-apps/api/path';
// Open a selection dialog for directories
const selected = await open({
  directory: true,
  multiple: true,
  defaultPath: await appDir(),
});
if (Array.isArray(selected)) {
  // user selected multiple directories
} else if (selected === null) {
  // user cancelled the selection
} else {
  // user selected a single directory
}
```
```

--------------------------------

### Capability Permissions Array

Source: https://v2.tauri.app/reference/acl/capability

This array lists the specific permissions, including core, shell, dialog, and filesystem access, that are granted by the capability.

```json
[
  "core:default",
  "shell:allow-open",
  "dialog:open",
  {
    "identifier": "fs:allow-write-text-file",
    "allow": [{ "path": "$HOME/test.txt" }]
  }
]
```

--------------------------------

### Configure Tauri Capability for FS Plugin Resource Access

Source: https://v2.tauri.app/develop/resources

Sets up the `main-capability` to allow `fs:allow-read-text-file` and `fs:allow-resource-read-recursive` permissions, enabling JavaScript to read resource files via the `fs` plugin.

```json
{
  "$schema": "../gen/schemas/desktop-schema.json",
  "identifier": "main-capability",
  "description": "Capability for the main window",
  "windows": ["main"],
  "permissions": [
    "core:default",
    "fs:allow-read-text-file",
    "fs:allow-resource-read-recursive"
  ]
}
```

--------------------------------

### Create a Webview within a Window

Source: https://v2.tauri.app/reference/javascript/api/namespacewebviewwindow

Demonstrates creating a Window and attaching a Webview to it after the window is successfully created.

```typescript
import { Window } from "@tauri-apps/api/window"
import { Webview } from "@tauri-apps/api/webview"


const appWindow = new Window('uniqueLabel');


appWindow.once('tauri://created', async function () {
  // `new Webview` Should be called after the window is successfully created,
  // or webview may not be attached to the window since window is not created yet.


  // loading embedded asset:
  const webview = new Webview(appWindow, 'theUniqueLabel', {
    url: 'path/to/page.html',


    // create a webview with specific logical position and size
    x: 0,
    y: 0,
    width: 800,
    height: 600,
  });
  // alternatively, load a remote URL:
  const webview = new Webview(appWindow, 'theUniqueLabel', {
    url: 'https://github.com/tauri-apps/tauri',


    // create a webview with specific logical position and size
    x: 0,
    y: 0,
    width: 800,
    height: 600,
  });


  webview.once('tauri://created', function () {
    // webview successfully created
  });
  webview.once('tauri://error', function (e) {
    // an error happened creating the webview
  });


  // emit an event to the backend
  await webview.emit("some-event", "data");
  // listen to an event from the backend
  const unlisten = await webview.listen("event-name", e => { });
  unlisten();
});
```

--------------------------------

### Configure Multi-Window Capabilities in Tauri

Source: https://v2.tauri.app/learn/mobile-multiwindow

Add the `core:webview:allow-create-webview-window` permission to your capability file to enable frontend creation of new windows. Use a wildcard or list all window labels in the `windows` array for multiple windows.

```json
{
  "$schema": "../gen/schemas/desktop-schema.json",
  "identifier": "default",
  "description": "Capability for the main window",
  "windows": ["main"],
  "permissions": ["core:default", "core:webview:allow-create-webview-window"]
}
```

