import type { ReactNode } from "react";

export type Workspace = "design" | "simulate" | "results" | "review";

export const WORKSPACES: { id: Workspace; label: string }[] = [
  { id: "design", label: "Design" },
  { id: "simulate", label: "Simulate" },
  { id: "results", label: "Results" },
  { id: "review", label: "Review" },
];

interface WorkbenchProps {
  workspace: Workspace;
  onWorkspaceChange: (workspace: Workspace) => void;
  disabledWorkspaces?: Workspace[];
  title: string;
  toolbar?: ReactNode;
  banner?: ReactNode;
  children: ReactNode;
}

export default function Workbench({
  workspace,
  onWorkspaceChange,
  disabledWorkspaces = [],
  title,
  toolbar,
  banner,
  children,
}: WorkbenchProps) {
  return (
    <div className="workbench">
      <header className="workbench-header">
        <h1 className="workbench-title">{title}</h1>
        <div className="workbench-toolbar">{toolbar}</div>
      </header>
      <nav className="workbench-tabs" role="tablist" aria-label="Workspaces">
        {WORKSPACES.map(({ id, label }) => {
          const disabled = disabledWorkspaces.includes(id);
          const active = workspace === id;
          return (
            <button
              key={id}
              type="button"
              role="tab"
              aria-selected={active}
              disabled={disabled}
              className={`workbench-tab${active ? " active" : ""}`}
              onClick={() => !disabled && onWorkspaceChange(id)}
            >
              {label}
            </button>
          );
        })}
      </nav>
      {banner && <div className="workbench-banner">{banner}</div>}
      <main className="workbench-content">{children}</main>
    </div>
  );
}

import type { Design } from "../core/types";

interface Props {
  design: Design;
  onChange: (next: Design) => void;
}

function Num({
  label,
  value,
  step,
  onChange,
}: {
  label: string;
  value: number;
  step?: number;
  onChange: (v: number) => void;
}) {
  return (
    <label style={{ display: "block", margin: "6px 0" }}>
      <span style={{ display: "inline-block", width: 150 }}>{label}</span>
      <input
        type="number"
        value={value}
        step={step ?? 1}
        style={{ width: 90 }}
        onChange={(e) => {
          const v = Number(e.target.value);
          if (Number.isFinite(v)) onChange(v);
        }}
      />
    </label>
  );
}

export default function Inspector({ design, onChange }: Props) {
  const dualDeploy = design.chute.main_deploy_altitude_m != null;

  return (
    <div>
      <h3>Rocket</h3>
      <label style={{ display: "block", margin: "6px 0" }}>
        <span style={{ display: "inline-block", width: 150 }}>Name</span>
        <input
          value={design.name}
          onChange={(e) => onChange({ ...design, name: e.target.value })}
        />
      </label>
      <Num
        label="Dry mass (g)"
        value={design.dry_mass_g}
        onChange={(v) => onChange({ ...design, dry_mass_g: v })}
      />
      <Num
        label="Diameter (mm)"
        value={design.diameter_mm}
        onChange={(v) => onChange({ ...design, diameter_mm: v })}
      />
      <Num
        label="Drag Cd"
        value={design.cd}
        step={0.01}
        onChange={(v) => onChange({ ...design, cd: v })}
      />
      <Num
        label="Rail length (m)"
        value={design.rail_length_m}
        step={0.1}
        onChange={(v) => onChange({ ...design, rail_length_m: v })}
      />
      <h3>Recovery</h3>
      <label style={{ display: "block", margin: "6px 0" }}>
        <span style={{ display: "inline-block", width: 150 }}>Parachute</span>
        <input
          type="checkbox"
          checked={design.chute.enabled}
          onChange={(e) =>
            onChange({ ...design, chute: { ...design.chute, enabled: e.target.checked } })
          }
        />
      </label>
      {design.chute.enabled && (
        <>
          <Num
            label="Chute diameter (cm)"
            value={design.chute.diameter_cm}
            onChange={(v) =>
              onChange({ ...design, chute: { ...design.chute, diameter_cm: v } })
            }
          />
          <Num
            label="Chute Cd"
            value={design.chute.cd}
            step={0.05}
            onChange={(v) => onChange({ ...design, chute: { ...design.chute, cd: v } })}
          />
          <label style={{ display: "block", margin: "6px 0" }}>
            <span style={{ display: "inline-block", width: 150 }}>Dual deploy</span>
            <input
              type="checkbox"
              checked={dualDeploy}
              onChange={(e) =>
                onChange({
                  ...design,
                  chute: e.target.checked
                    ? {
                        ...design.chute,
                        main_deploy_altitude_m: 60,
                        drogue_diameter_cm: 8,
                        drogue_cd: 0.8,
                      }
                    : {
                        ...design.chute,
                        main_deploy_altitude_m: null,
                        drogue_diameter_cm: null,
                        drogue_cd: null,
                      },
                })
              }
            />
          </label>
          {dualDeploy && (
            <>
              <Num
                label="Main deploy AGL (m)"
                value={design.chute.main_deploy_altitude_m ?? 60}
                onChange={(v) =>
                  onChange({
                    ...design,
                    chute: { ...design.chute, main_deploy_altitude_m: v },
                  })
                }
              />
              <Num
                label="Drogue diameter (cm)"
                value={design.chute.drogue_diameter_cm ?? 8}
                onChange={(v) =>
                  onChange({
                    ...design,
                    chute: { ...design.chute, drogue_diameter_cm: v },
                  })
                }
              />
              <Num
                label="Drogue Cd"
                value={design.chute.drogue_cd ?? 0.8}
                step={0.05}
                onChange={(v) =>
                  onChange({
                    ...design,
                    chute: { ...design.chute, drogue_cd: v },
                  })
                }
              />
            </>
          )}
        </>
      )}
    </div>
  );
}

:root {
  --ascent-bg: #0a0d12;
  --ascent-bg-elevated: #11151c;
  --ascent-bg-panel: #161b23;
  --ascent-border: #262d38;
  --ascent-border-strong: #384252;

  --ascent-text: #e6e8eb;
  --ascent-text-dim: #9aa1ab;
  --ascent-text-faint: #5b6472;

  --ascent-accent: #58a6ff;
  --ascent-ok: #3fb950;
  --ascent-warn: #e8a33d;
  --ascent-danger: #c74b3c;

  --ascent-font-sans: system-ui, sans-serif;
  --ascent-font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  --ascent-space-1: 4px;
  --ascent-space-2: 8px;
  --ascent-space-3: 12px;
  --ascent-space-4: 16px;
  --ascent-space-5: 24px;

  --ascent-radius: 6px;
}

* {
  box-sizing: border-box;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  appearance: none;
  min-height: 30px;
  padding: var(--ascent-space-1) var(--ascent-space-3);
  border: 1px solid var(--ascent-border-strong);
  border-radius: var(--ascent-radius);
  background: var(--ascent-bg-panel);
  color: var(--ascent-text);
  cursor: pointer;
}

button:hover:not(:disabled) {
  border-color: var(--ascent-accent);
  background: var(--ascent-bg-elevated);
}

input,
select,
textarea {
  border: 1px solid var(--ascent-border-strong);
  border-radius: var(--ascent-radius);
  background: var(--ascent-bg-elevated);
  color: var(--ascent-text);
  padding: var(--ascent-space-1) var(--ascent-space-2);
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--ascent-accent);
  outline-offset: 2px;
}

button:disabled,
input:disabled,
select:disabled,
textarea:disabled {
  color: var(--ascent-text-faint);
  border-color: var(--ascent-border);
  cursor: not-allowed;
  opacity: 0.65;
}

.workbench {
  display: grid;
  grid-template-rows: auto auto auto 1fr;
  min-height: 100vh;
  background: var(--ascent-bg);
  color: var(--ascent-text);
  font-family: var(--ascent-font-sans);
}

.workbench-header {
  display: flex;
  align-items: center;
  gap: var(--ascent-space-4);
  padding: var(--ascent-space-3) var(--ascent-space-5);
  background: var(--ascent-bg-elevated);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ascent-text);
}

.workbench-toolbar {
  display: flex;
  align-items: center;
  gap: var(--ascent-space-2);
  margin-left: auto;
}

.workbench-tabs {
  display: flex;
  gap: var(--ascent-space-1);
  padding: 0 var(--ascent-space-5);
  background: var(--ascent-bg-elevated);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-tab {
  appearance: none;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--ascent-text-dim);
  font: inherit;
  font-size: 13px;
  letter-spacing: 0.02em;
  padding: var(--ascent-space-3) var(--ascent-space-2);
  cursor: pointer;
}

.workbench-tab:hover:not(:disabled) {
  color: var(--ascent-text);
}

.workbench-tab.active {
  color: var(--ascent-accent);
  border-bottom-color: var(--ascent-accent);
}

.workbench-tab:disabled {
  color: var(--ascent-text-faint);
  cursor: not-allowed;
}

.workbench-banner {
  padding: var(--ascent-space-2) var(--ascent-space-5);
  background: var(--ascent-bg-panel);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-content {
  padding: var(--ascent-space-5);
  overflow: auto;
}

.design-workspace {
  display: grid;
  grid-template-columns: minmax(360px, 1.4fr) minmax(240px, 0.8fr) minmax(220px, 0.7fr);
  align-items: start;
  gap: var(--ascent-space-5);
}

.viewport-panel {
  min-width: 0;
  padding: var(--ascent-space-3);
  overflow: hidden;
  border: 1px solid var(--ascent-border);
  border-radius: var(--ascent-radius);
  background: var(--ascent-bg-panel);
}

.viewport-panel > svg {
  display: block;
  max-width: 100%;
  margin-inline: auto;
}

.viewport-r3f,
.viewport-loading,
.viewport-error {
  width: 100%;
  min-height: clamp(360px, 58vh, 760px);
  overflow: hidden;
  border: 1px solid var(--ascent-border-strong);
  border-radius: var(--ascent-radius);
  background: radial-gradient(circle at 50% 35%, #1b2430 0%, var(--ascent-bg) 72%);
}

.viewport-r3f canvas {
  display: block;
}

.viewport-loading,
.viewport-error {
  display: grid;
  place-items: center;
  color: var(--ascent-text-dim);
  font-family: var(--ascent-font-mono);
  font-size: 13px;
}

.viewport-error {
  color: var(--ascent-danger);
}

.command-palette-overlay {
  position: fixed;
  inset: 0;
  background: rgba(10, 13, 18, 0.6);
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-top: 12vh;
  z-index: 1000;
}

.command-palette {
  width: min(560px, 90vw);
  background: var(--ascent-bg-panel);
  border: 1px solid var(--ascent-border-strong);
  border-radius: var(--ascent-radius);
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.5);
  overflow: hidden;
}

.command-palette-input {
  width: 100%;
  padding: var(--ascent-space-3) var(--ascent-space-4);
  background: var(--ascent-bg-elevated);
  border: none;
  border-bottom: 1px solid var(--ascent-border);
  color: var(--ascent-text);
  font-family: var(--ascent-font-mono);
  font-size: 14px;
  outline: none;
}

.command-palette-error {
  padding: var(--ascent-space-2) var(--ascent-space-4);
  color: var(--ascent-danger);
  font-family: var(--ascent-font-mono);
  font-size: 12px;
  border-bottom: 1px solid var(--ascent-border);
}

.command-palette-list {
  list-style: none;
  margin: 0;
  padding: var(--ascent-space-1) 0;
  max-height: 360px;
  overflow-y: auto;
}

.command-palette-item {
  display: flex;
  align-items: baseline;
  gap: var(--ascent-space-3);
  padding: var(--ascent-space-2) var(--ascent-space-4);
  cursor: pointer;
  font-family: var(--ascent-font-mono);
  font-size: 13px;
  color: var(--ascent-text-dim);
}

.command-palette-item.selected {
  background: var(--ascent-bg-elevated);
  color: var(--ascent-text);
}

.command-palette-item-title {
  color: inherit;
}

.command-palette-item-subtitle {
  color: var(--ascent-text-faint);
  font-size: 11px;
}

.command-palette-empty {
  padding: var(--ascent-space-3) var(--ascent-space-4);
  color: var(--ascent-text-faint);
  font-family: var(--ascent-font-mono);
  font-size: 13px;
}

@media (max-width: 960px) {
  .workbench-header,
  .workbench-toolbar {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .workbench-toolbar {
    margin-left: 0;
  }

  .workbench-content {
    padding: var(--ascent-space-3);
  }

  .design-workspace {
    grid-template-columns: 1fr;
  }

  .viewport-r3f,
  .viewport-loading,
  .viewport-error {
    min-height: clamp(360px, 58vh, 760px);
  }
}

import type { AtmosphereProfile } from "../core/types";

interface Props {
  profile: AtmosphereProfile | null;
  onImport: (name: string, csv: string) => Promise<void>;
  onClear: () => Promise<void>;
}

export default function AtmospherePanel({ profile, onImport, onClear }: Props) {
  return (
    <section>
      <h3>Atmosphere</h3>
      <p>
        {profile
          ? `${profile.name} · ${profile.layers.length} levels`
          : "Analytic atmosphere"}
      </p>
      <label>
        Import atmosphere CSV
        <input
          type="file"
          accept=".csv,text/csv"
          onChange={async (event) => {
            const input = event.currentTarget;
            const file = input.files?.[0];
            if (!file) return;
            await onImport(file.name, await file.text());
            input.value = "";
          }}
        />
      </label>
      {profile && <button onClick={() => void onClear()}>Use analytic atmosphere</button>}
    </section>
  );
}

