:root {
  --ascent-bg: #0a0d12;
  --ascent-bg-elevated: #11151c;
  --ascent-bg-panel: #161b23;
  --ascent-border: #262d38;
  --ascent-border-strong: #384252;

  --ascent-text: #e6e8eb;
  --ascent-text-dim: #9aa1ab;
  --ascent-text-faint: #5b6472;

  --ascent-accent: #58a6ff;
  --ascent-ok: #3fb950;
  --ascent-warn: #e8a33d;
  --ascent-danger: #c74b3c;

  --ascent-font-sans: system-ui, sans-serif;
  --ascent-font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  --ascent-space-1: 4px;
  --ascent-space-2: 8px;
  --ascent-space-3: 12px;
  --ascent-space-4: 16px;
  --ascent-space-5: 24px;

  --ascent-radius: 6px;
}

* {
  box-sizing: border-box;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  appearance: none;
  min-height: 30px;
  padding: var(--ascent-space-1) var(--ascent-space-3);
  border: 1px solid var(--ascent-border-strong);
  border-radius: var(--ascent-radius);
  background: var(--ascent-bg-panel);
  color: var(--ascent-text);
  cursor: pointer;
}

button:hover:not(:disabled) {
  border-color: var(--ascent-accent);
  background: var(--ascent-bg-elevated);
}

input,
select,
textarea {
  border: 1px solid var(--ascent-border-strong);
  border-radius: var(--ascent-radius);
  background: var(--ascent-bg-elevated);
  color: var(--ascent-text);
  padding: var(--ascent-space-1) var(--ascent-space-2);
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--ascent-accent);
  outline-offset: 2px;
}

button:disabled,
input:disabled,
select:disabled,
textarea:disabled {
  color: var(--ascent-text-faint);
  border-color: var(--ascent-border);
  cursor: not-allowed;
  opacity: 0.65;
}

.workbench {
  display: grid;
  grid-template-rows: auto auto auto 1fr;
  min-height: 100vh;
  background: var(--ascent-bg);
  color: var(--ascent-text);
  font-family: var(--ascent-font-sans);
}

.workbench-header {
  display: flex;
  align-items: center;
  gap: var(--ascent-space-4);
  padding: var(--ascent-space-3) var(--ascent-space-5);
  background: var(--ascent-bg-elevated);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ascent-text);
}

.workbench-toolbar {
  display: flex;
  align-items: center;
  gap: var(--ascent-space-2);
  margin-left: auto;
}

.workbench-tabs {
  display: flex;
  gap: var(--ascent-space-1);
  padding: 0 var(--ascent-space-5);
  background: var(--ascent-bg-elevated);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-tab {
