}

.workbench-tab:disabled {
  color: var(--ascent-text-faint);
  cursor: not-allowed;
}

.workbench-banner {
  padding: var(--ascent-space-2) var(--ascent-space-5);
  background: var(--ascent-bg-panel);
  border-bottom: 1px solid var(--ascent-border);
}

.workbench-content {
  padding: var(--ascent-space-5);
  overflow: auto;
}

.design-workspace {
  display: grid;
  grid-template-columns: minmax(360px, 1.4fr) minmax(240px, 0.8fr) minmax(220px, 0.7fr);
  align-items: start;
  gap: var(--ascent-space-5);
}

.viewport-panel {
  min-width: 0;
  padding: var(--ascent-space-3);
