import {
  ArrowRight,
  CheckCircle,
  CirclesThreePlus,
  Robot,
  ShieldCheck,
  Warning,
} from "@phosphor-icons/react";
import { useMemo, useState } from "react";
import type { CommandProposal, DocumentState } from "../core/types";
import { applyProposal, proposeCommands } from "../ipc";

interface Props {
  onDocChange: (doc: DocumentState) => void;
  onApplied: () => void;
}

const STARTER_COMMANDS = [
  { label: "Refine drag model", command: "set-sim-param cd 0.58" },
  { label: "Use a longer rail", command: "set-sim-param rail_length_m 1.5" },
  { label: "Select C6 motor", command: "select-motor C6" },
];

export default function CopilotPanel({ onDocChange, onApplied }: Props) {
  const [draft, setDraft] = useState(STARTER_COMMANDS[0].command);
  const [proposal, setProposal] = useState<CommandProposal | null>(null);
  const [busy, setBusy] = useState<"preview" | "apply" | null>(null);
  const [error, setError] = useState<string | null>(null);

  const lines = useMemo(
    () => draft.split("\n").map((line) => line.trim()).filter(Boolean),
    [draft],
  );

  const preview = async () => {
    if (lines.length === 0) return;
    setBusy("preview");
    setError(null);
    try {
      setProposal(await proposeCommands(lines));
    } catch (e) {
      setProposal(null);
      setError(String(e));
    } finally {
      setBusy(null);
    }
  };

  const apply = async () => {
    if (!proposal?.valid) return;
    setBusy("apply");
    setError(null);
    try {
      onDocChange(await applyProposal(lines));
      onApplied();
      setProposal(null);
    } catch (e) {
      setError(String(e));
    } finally {
      setBusy(null);
    }
  };

  const diff = proposal?.diff;
  const changeCount = diff
    ? Number(diff.vehicle_changed) +
      Number(diff.design_changed) +
      Number(diff.atmosphere_changed) +
      diff.parts_added +
      diff.parts_removed +
      diff.studies_added +
      diff.studies_removed
    : 0;

  return (
    <div className="copilot-panel">
      <div className="copilot-intro">
        <div className="copilot-mark"><Robot size={20} weight="duotone" /></div>
        <div>
          <div className="copilot-title-row">
            <h3>AI Command Copilot</h3>
            <span className="agent-state"><span /> Agent bridge ready</span>
          </div>
          <p>
            Agents use the same journaled command layer as the GUI. Every batch is dry-run,
            checked for stale evidence, and requires your approval.
          </p>
        </div>
      </div>

      <div className="copilot-body">
        <div className="copilot-compose">
          <label htmlFor="copilot-command">Proposed command batch</label>
          <textarea
            id="copilot-command"
            value={draft}
            spellCheck={false}
            onChange={(event) => {
              setDraft(event.target.value);
              setProposal(null);
            }}
            placeholder="set-part-param 3 span_m 0.05"
          />
          <div className="copilot-suggestions" aria-label="Suggested command batches">
            {STARTER_COMMANDS.map((starter) => (
              <button
                type="button"
                key={starter.label}
                onClick={() => {
                  setDraft(starter.command);
                  setProposal(null);
                }}
              >
                <CirclesThreePlus size={13} />
                {starter.label}
              </button>
            ))}
          </div>
        </div>

        <div className="proposal-review" aria-live="polite">
          {!proposal && !error && (
            <div className="proposal-empty">
              <ShieldCheck size={23} weight="duotone" />
              <span>Preview to inspect the exact diff and evidence impact.</span>
            </div>
          )}
          {error && <div className="proposal-error"><Warning size={16} />{error}</div>}
          {proposal && (
            <>
              <div className={`proposal-verdict ${proposal.valid ? "valid" : "invalid"}`}>
                {proposal.valid ? <CheckCircle size={17} weight="fill" /> : <Warning size={17} weight="fill" />}
                <strong>{proposal.valid ? "Validated" : "Revision required"}</strong>
                <span>{proposal.commands.length} command{proposal.commands.length === 1 ? "" : "s"}</span>
              </div>
              <div className="proposal-lines">
                {proposal.commands.map((command) => (
                  <div key={command.index} className={command.error ? "has-error" : ""}>
                    <code>{command.text}</code>
                    {command.error && <span>{command.error}</span>}
                  </div>
                ))}
              </div>
              {diff && (
                <div className="proposal-impact">
                  <span><strong>{changeCount}</strong> state changes</span>
                  <span className={diff.studies_made_stale.length > 0 ? "warning" : ""}>
                    <strong>{diff.studies_made_stale.length}</strong> studies made stale
                  </span>
                  <span><strong>1</strong> atomic journal entry</span>
                </div>
              )}
            </>
          )}
        </div>

        <div className="copilot-actions">
          <button type="button" className="button-secondary" onClick={() => void preview()} disabled={busy !== null || lines.length === 0}>
            {busy === "preview" ? "Checking…" : "Preview changes"}
          </button>
          <button type="button" className="button-primary" onClick={() => void apply()} disabled={!proposal?.valid || busy !== null}>
            {busy === "apply" ? "Applying…" : "Approve & apply"}
            <ArrowRight size={14} weight="bold" />
          </button>
        </div>
      </div>
    </div>
  );
}

import {
  ChartLineUp,
  Cube,
  Gauge,
  RocketLaunch,
  ShieldCheck,
} from "@phosphor-icons/react";
import type { Icon } from "@phosphor-icons/react";
import type { ReactNode } from "react";

export type Workspace = "design" | "simulate" | "results" | "review";

export const WORKSPACES: { id: Workspace; label: string; icon: Icon; key: string }[] = [
  { id: "design", label: "Design", icon: Cube, key: "1" },
  { id: "simulate", label: "Simulate", icon: Gauge, key: "2" },
  { id: "results", label: "Results", icon: ChartLineUp, key: "3" },
  { id: "review", label: "Review", icon: ShieldCheck, key: "4" },
];

interface WorkbenchProps {
  workspace: Workspace;
  onWorkspaceChange: (workspace: Workspace) => void;
  disabledWorkspaces?: Workspace[];
  title: string;
  projectName?: string;
  toolbar?: ReactNode;
  banner?: ReactNode;
  statusbar?: ReactNode;
  children: ReactNode;
}

export default function Workbench({
  workspace,
  onWorkspaceChange,
  disabledWorkspaces = [],
  title,
  projectName,
  toolbar,
  banner,
  statusbar,
  children,
}: WorkbenchProps) {
  const active = WORKSPACES.find((item) => item.id === workspace) ?? WORKSPACES[0];
  return (
    <div className="workbench">
      <header className="workbench-header">
        <div className="workbench-brand">
          <span className="brand-mark"><RocketLaunch size={19} weight="fill" /></span>
          <h1 className="workbench-title">{title}</h1>
          {projectName && (
            <>
              <span className="title-divider" aria-hidden="true" />
              <span className="project-title">{projectName}</span>
              <span className="project-dirty" title="Document has local state" />
            </>
          )}
        </div>
        <div className="workbench-toolbar">{toolbar}</div>
      </header>

      {banner && <div className="workbench-banner">{banner}</div>}

      <div className="workbench-frame">
        <nav className="activity-rail" role="tablist" aria-label="Workspaces">
          {WORKSPACES.map(({ id, label, icon: WorkspaceIcon, key }) => {
            const disabled = disabledWorkspaces.includes(id);
            const selected = workspace === id;
            return (
              <button
                key={id}
                type="button"
                role="tab"
                aria-selected={selected}
                aria-label={label}
                title={`${label} workspace (${key})`}
                disabled={disabled}
                className={`activity-button${selected ? " active" : ""}`}
                onClick={() => !disabled && onWorkspaceChange(id)}
              >
                <WorkspaceIcon size={20} weight={selected ? "fill" : "regular"} />
                <span className="sr-only">{label}</span>
                <kbd>{key}</kbd>
              </button>
            );
          })}
        </nav>

        <section className="workbench-surface">
          <div className="workspace-contextbar">
            <span className="workspace-name">{active.label}</span>
            <span className="workspace-separator">/</span>
            <span className="workspace-context">{workspace === "design" ? "Vehicle assembly" : workspace === "simulate" ? "Flight playback" : workspace === "results" ? "Post-processing" : "Mission assurance"}</span>
            <span className="workspace-engine">ASCENT SOLVER · LOCAL</span>
          </div>
          <main className="workbench-content">{children}</main>
        </section>
      </div>

      <footer className="statusbar">{statusbar}</footer>
    </div>
  );
}

