  --font-ui: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI Variable", "Segoe UI", sans-serif;
  --font-mono: "SFMono-Regular", "SF Mono", Menlo, Monaco, Consolas, monospace;
  --grid-minor: rgba(154, 161, 171, 0.045);
  --grid-major: rgba(154, 161, 171, 0.085);
  --radius: 3px;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  background: var(--bg-app);
  color: var(--text);
  font-family: var(--font-ui);
  font-size: 12px;
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;
  text-rendering: geometricPrecision;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  appearance: none;
  min-height: 26px;
  padding: 3px 9px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  background: var(--bg-panel-raised);
  color: var(--text);
  cursor: pointer;
  line-height: 1;
}

button:hover:not(:disabled) {
  border-color: #5c616b;
  background: var(--bg-hover);
}

button:active:not(:disabled) {
  transform: translateY(1px);
}

button:disabled,
input:disabled,
select:disabled,
textarea:disabled {
  color: var(--text-faint);
  cursor: not-allowed;
  opacity: 0.58;
}

input,
select,
textarea {
  min-height: 26px;
  border: 1px solid var(--border);
  border-radius: 2px;
  background: var(--bg-input);
  color: var(--text);
  padding: 3px 7px;
}

input:hover,
select:hover,
textarea:hover {
  border-color: var(--border-strong);
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:focus-visible {
  outline: 1px solid var(--accent-strong);
  outline-offset: 1px;
}

input[type="checkbox"] {
  accent-color: var(--accent);
  min-height: auto;
}

input[type="range"] {
  accent-color: var(--accent);
}

progress {
  height: 5px;
  border: 0;
  border-radius: 0;
  overflow: hidden;
  background: var(--bg-input);
}

progress::-webkit-progress-bar { background: var(--bg-input); }
progress::-webkit-progress-value { background: var(--blue); }

kbd,
code,
pre {
  font-family: var(--font-mono);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.boot-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  height: 100%;
  background: var(--bg-app);
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

.boot-screen strong,
.boot-screen span { display: block; }
.boot-screen strong { color: var(--text); font-size: 12px; letter-spacing: 0.11em; }
.boot-screen span { margin-top: 4px; font-size: 11px; }
.boot-mark { color: var(--accent); }

.workbench {
  display: grid;
  grid-template-rows: 38px auto minmax(0, 1fr) 23px;
  width: 100%;
  height: 100dvh;
  min-width: 860px;
  background: var(--bg-app);
  color: var(--text);
}

.workbench-header {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  padding: 0 7px 0 11px;
  background: var(--bg-chrome);
  border-bottom: 1px solid var(--border-subtle);
  -webkit-user-select: none;
  user-select: none;
}

.workbench-brand {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 8px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 23px;
  height: 23px;
  color: var(--accent-strong);
}

.workbench-title {
  margin: 0;
  color: #f0f0f1;
  font-size: 12px;
  font-weight: 720;
  letter-spacing: 0.105em;
  text-transform: uppercase;
}

.title-divider {
  width: 1px;
  height: 16px;
  margin: 0 2px;
  background: var(--border);
}

.project-title {
  max-width: 260px;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 11.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-dirty {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--yellow);
}

.workbench-toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  margin-left: auto;
}

.toolbar-button,
.toolbar-overflow,
.run-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 27px;
  min-height: 27px;
  padding: 0 8px;
  border-color: transparent;
  background: transparent;
  color: var(--text-muted);
  font-size: 11.5px;
}

.toolbar-button:hover:not(:disabled),
.toolbar-overflow:hover:not(:disabled) {
  border-color: var(--border);
  background: var(--bg-hover);
  color: var(--text);
}

.toolbar-button kbd {
  margin-left: 2px;
  color: var(--text-faint);
  font-size: 9px;
}

.toolbar-divider {
  display: inline-block;
  flex: 0 0 auto;
  width: 1px;
  height: 17px;
  margin: 0 2px;
  background: var(--border);
}

.toolbar-button.ai-entry {
  border-color: #4b403a;
  background: rgba(217, 120, 75, 0.055);
  color: #d8c2b7;
}

.toolbar-button.ai-entry svg { color: var(--accent-strong); }

.run-button {
  padding-inline: 12px;
  border-color: #a95734;
  background: #a95734;
  color: #fff;
  font-weight: 620;
}

.run-button:hover:not(:disabled) {
  border-color: var(--accent-strong);
  background: #bc633d;
}

.run-state {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-right: 2px;
  color: var(--text-muted);
  font-size: 10.5px;
  white-space: nowrap;
}

.run-state > span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-faint);
}

.run-state.ok > span { background: var(--green); }
.run-state.warn > span { background: var(--yellow); }
.run-state.active > span { background: var(--blue); }
.run-state.danger > span { background: var(--red); }

.workbench-banner {
  background: var(--bg-chrome);
  border-bottom: 1px solid var(--border);
}

.notice-bar {
  display: flex;
  align-items: center;
  min-height: 32px;
  gap: 8px;
  padding: 3px 10px 3px 60px;
  color: var(--text-muted);
}

.notice-bar.warning svg { color: var(--yellow); }
.notice-bar.danger svg,
.notice-bar.danger { color: #e08a82; }
.notice-bar button { min-height: 22px; padding: 2px 7px; margin-left: 2px; }

.workbench-frame {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  min-height: 0;
}

.activity-rail {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
  padding: 5px 4px;
  background: var(--bg-rail);
  border-right: 1px solid var(--border-subtle);
}

.activity-button {
  position: relative;
  display: grid;
  place-items: center;
  width: 39px;
  height: 42px;
  min-height: 42px;
  padding: 0;
  border-color: transparent;
  background: transparent;
  color: var(--text-faint);
}

.activity-button:hover:not(:disabled) {
  border-color: transparent;
  background: var(--bg-hover);
  color: var(--text);
}

.activity-button::before {
  content: "";
  position: absolute;
  left: -4px;
  width: 2px;
  height: 20px;
  background: transparent;
}

.activity-button.active {
  background: #25272c;
  color: var(--accent-strong);
}

.activity-button.active::before { background: var(--accent); }

.activity-button kbd {
  position: absolute;
  right: 3px;
  bottom: 2px;
  color: #555b65;
  font-size: 8px;
}

.workbench-surface {
  display: grid;
  grid-template-rows: 27px minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
}

.workspace-contextbar {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 7px;
  padding: 0 9px;
  background: #191b1e;
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-faint);
  font-size: 10.5px;
}

.workspace-name { color: var(--text); font-weight: 620; }
.workspace-separator { color: #4d525a; }
.workspace-engine {
  margin-left: auto;
  color: #656b74;
  font-family: var(--font-mono);
  font-size: 9.5px;
  letter-spacing: 0.05em;
}

.workbench-content {
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.engineering-layout {
  display: grid;
  grid-template-columns: 236px minmax(360px, 1fr) 292px;
  grid-template-rows: minmax(310px, 1fr) 238px;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}

.model-browser,
.properties-panel,
.viewport-workspace,
.workbench-dock {
  min-width: 0;
  min-height: 0;
  background: var(--bg-panel);
}

.model-browser {
  grid-row: 1 / 3;
  border-right: 1px solid var(--border);
  overflow: auto;
}

.properties-panel {
  grid-column: 3;
  grid-row: 1 / 3;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-left: 1px solid var(--border);
}

.viewport-workspace {
  grid-column: 2;
  grid-row: 1;
  display: grid;
  grid-template-rows: 36px minmax(0, 1fr);
  background: var(--bg-canvas);
}

.workbench-dock {
  grid-column: 2;
  grid-row: 2;
  display: grid;
  grid-template-rows: 31px minmax(0, 1fr);
  border-top: 1px solid var(--border);
}

.panel-heading,
.panel-chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 42px;
  padding: 7px 9px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-chrome);
}

.panel-chrome {
  min-height: 36px;
  height: 36px;
  padding-block: 4px;
}

.panel-heading h2,
.panel-chrome h2 {
  margin: 1px 0 0;
  color: var(--text);
  font-size: 11.5px;
  font-weight: 640;
}

.panel-eyebrow {
  display: block;
  color: var(--text-faint);
  font-size: 8.5px;
  font-weight: 650;
  letter-spacing: 0.09em;
  line-height: 1;
  text-transform: uppercase;
}

.panel-count,
.dock-count {
  display: inline-grid;
  place-items: center;
  min-width: 17px;
  height: 16px;
  padding: 0 4px;
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-faint);
  font-family: var(--font-mono);
  font-size: 9px;
}

.project-explorer { min-height: 100%; }

.tree-section {
  padding: 5px 0;
  border-bottom: 1px solid var(--border-subtle);
}

.tree-section-label {
  padding: 6px 9px 4px;
  color: #777c85;
  font-size: 8.5px;
  font-weight: 680;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.tree-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.tree-row {
  --tree-depth: 0;
  display: grid;
  grid-template-columns: 11px 15px minmax(0, 1fr) auto;
  align-items: center;
  gap: 4px;
  width: 100%;
  height: 25px;
  min-height: 25px;
  padding: 0 8px 0 calc(7px + var(--tree-depth) * 14px);
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--text-muted);
  text-align: left;
}

.tree-row:hover:not(:disabled) {
  border: 0;
  background: var(--bg-hover);
}

.tree-row.selected {
  background: var(--accent-soft);
  color: #f0d7ca;
  box-shadow: inset 2px 0 0 var(--accent);
}

.tree-root { font-weight: 620; }
.tree-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tree-meta { color: var(--text-faint); font-family: var(--font-mono); font-size: 9px; }
.tree-disclosure { display: grid; place-items: center; width: 11px; }
.tree-status { width: 6px; height: 6px; border-radius: 50%; background: var(--text-faint); }
.tree-status.complete { background: var(--green); }
.tree-status.pending { background: var(--yellow); }
.tree-empty { padding: 7px 10px 9px 25px; color: var(--text-faint); font-size: 10.5px; }

.canvas-toolbar {
  display: flex;
  align-items: center;
  gap: 2px;
}

.canvas-toolbar button {
  display: grid;
  place-items: center;
  height: 24px;
  min-height: 24px;
  min-width: 27px;
  padding: 0 6px;
  border-color: transparent;
  background: transparent;
  color: var(--text-faint);
  font-size: 10px;
}

.canvas-toolbar button:hover:not(:disabled) { border-color: var(--border); color: var(--text); }
.canvas-toolbar button.active,
.canvas-toolbar button:disabled { background: #33363c; color: var(--text); opacity: 1; }

.viewport-stage {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--bg-canvas);
}

.vehicle-drawing {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 300px;
}

.drawing-centerline { stroke: #6d727b; stroke-width: 0.8; stroke-dasharray: 10 8 2 8; opacity: 0.65; }
.drawing-axis-label,
.drawing-marker-label,
.drawing-dimensions text,
.drawing-titleblock text { fill: #8d929a; font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.04em; }
.drawing-seam { stroke: #555a62; stroke-width: 1; }
.drawing-recovery-marker { fill: #2d2925; stroke: var(--yellow); stroke-width: 1; }
.drawing-recovery-icon { fill: none; stroke: var(--yellow); stroke-width: 1; }
.drawing-marker-label { font-size: 9px; }
.marker-line { stroke-width: 1; stroke-dasharray: 3 3; opacity: 0.7; }
.marker-line.cg { stroke: var(--blue); }
.marker-line.cp { stroke: var(--yellow); }
.marker-point { fill: var(--bg-canvas); stroke-width: 2; }
.marker-point.cg { stroke: var(--blue); }
.marker-point.cp { stroke: var(--yellow); }
.marker-label.cg { fill: var(--blue); }
.marker-label.cp { fill: var(--yellow); }
.drawing-dimensions { fill: #777c85; stroke: #777c85; stroke-width: 0.8; }
.drawing-dimensions text { stroke: none; }
.drawing-titleblock rect { fill: rgba(24, 26, 30, 0.88); stroke: #545962; }
.drawing-titleblock .titleblock-name { fill: #d4d6da; font-size: 10.5px; font-weight: 700; }

.viewport-axis-tag,
.viewport-mode-tag {
  position: absolute;
  z-index: 2;
  top: 8px;
  color: var(--text-faint);
  font-family: var(--font-mono);
  font-size: 8.5px;
  letter-spacing: 0.05em;
}

.viewport-axis-tag { left: 9px; color: var(--green); }
.viewport-mode-tag { right: 9px; }

.viewport-readout {
  position: absolute;
  z-index: 2;
  bottom: 8px;
  left: 9px;
  display: grid;
  grid-template-columns: repeat(4, auto);
  border: 1px solid rgba(88, 93, 102, 0.7);
  background: rgba(24, 26, 30, 0.9);
}

.viewport-readout > div {
  display: grid;
  grid-template-columns: auto auto;
  gap: 8px;
  padding: 5px 7px;
  border-right: 1px solid var(--border);
}

.viewport-readout > div:last-child { border-right: 0; }
.viewport-readout span { color: var(--text-faint); font-size: 8px; letter-spacing: 0.06em; }
.viewport-readout strong { color: #d5d7db; font-family: var(--font-mono); font-size: 9px; font-weight: 500; }

.viewport-r3f,
.viewport-loading,
.viewport-error {
  width: 100%;
  height: 100%;
  min-height: 300px;
  overflow: hidden;
  background-color: var(--bg-canvas);
  background-image:
    linear-gradient(var(--grid-major) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-major) 1px, transparent 1px),
    linear-gradient(var(--grid-minor) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-minor) 1px, transparent 1px);
  background-size: 100px 100px, 100px 100px, 20px 20px, 20px 20px;
}

.viewport-r3f canvas { display: block; }
.viewport-loading,
.viewport-error { display: grid; place-items: center; color: var(--text-muted); font-family: var(--font-mono); font-size: 11px; }
.viewport-error { color: var(--red); }

.properties-heading { min-height: 42px; }
.properties-heading > svg { color: var(--text-faint); }
.properties-scroll { min-height: 0; overflow: auto; }

.property-group {
  margin: 0;
  padding: 0 9px 9px;
  border-bottom: 1px solid var(--border);
}

.property-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 31px;
  color: #c5c8cd;
  font-size: 10px;
  font-weight: 660;
  letter-spacing: 0.035em;
  text-transform: uppercase;
}

.property-group-heading span:last-child { color: #5e636c; font-family: var(--font-mono); font-size: 8.5px; }

.property-row {
  display: grid;
  grid-template-columns: minmax(92px, 1fr) minmax(80px, 112px);
  align-items: center;
  gap: 8px;
  min-height: 30px;
  border-top: 1px solid rgba(52, 55, 61, 0.62);
  color: var(--text-muted);
}

.property-row:first-of-type { border-top-color: transparent; }
.property-label { min-width: 0; color: var(--text-muted); font-size: 10.5px; }
.property-input-wrap { display: block; }
.property-row input[type="number"],
.property-text { width: 100%; text-align: right; font-family: var(--font-mono); font-size: 10.5px; }
.property-text { grid-column: 2; text-align: left; font-family: var(--font-ui); }
.property-toggle-row input { justify-self: end; width: 14px; height: 14px; }
.property-row-stacked { grid-template-columns: 1fr; gap: 4px; padding: 5px 0 7px; }
.property-row-stacked select { width: 100%; font-size: 10.5px; }
.property-readonly { display: flex; justify-content: space-between; gap: 8px; padding: 7px 0 2px; color: var(--text-faint); font-size: 9.5px; }
.property-readonly strong { color: var(--text-muted); font-weight: 500; }

.atmosphere-state {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 27px;
  color: var(--text-muted);
  font-size: 10px;
}

.atmosphere-state > span { width: 6px; height: 6px; border-radius: 50%; }
.profile-active { background: var(--blue); }
.profile-default { background: var(--green); }

.file-import-button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 26px;
  margin-top: 5px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  background: var(--bg-panel-raised);
  color: var(--text-muted);
  cursor: pointer;
  font-size: 10.5px;
}

.file-import-button:hover { border-color: #5c616b; background: var(--bg-hover); color: var(--text); }
.file-import-button input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
.property-action { width: 100%; margin-top: 5px; }

.button-primary,
.button-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 25px;
  font-size: 10.5px;
}

.button-primary { border-color: #a95734; background: #a95734; color: white; }
.button-primary:hover:not(:disabled) { border-color: var(--accent-strong); background: #bc633d; }
.button-secondary { background: var(--bg-panel-raised); color: var(--text-muted); }

.dock-header {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  padding: 0 7px 0 0;
  background: var(--bg-chrome);
  border-bottom: 1px solid var(--border);
}

.dock-tabs { display: flex; align-items: stretch; }
.dock-tabs button {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 30px;
  min-height: 30px;
  padding: 0 10px;
  border: 0;
  border-right: 1px solid var(--border-subtle);
  border-radius: 0;
  background: transparent;
  color: var(--text-faint);
  font-size: 10.5px;
}
.dock-tabs button:hover:not(:disabled) { border-color: var(--border-subtle); background: var(--bg-hover); color: var(--text); }
.dock-tabs button.active { background: var(--bg-panel); color: var(--text); box-shadow: inset 0 2px 0 var(--accent); }
.dock-live { width: 5px; height: 5px; border-radius: 50%; background: var(--green); }
.dock-context { align-self: center; color: var(--text-faint); font-family: var(--font-mono); font-size: 9px; text-transform: uppercase; }
.dock-content { min-width: 0; min-height: 0; overflow: auto; }

.copilot-panel { display: grid; grid-template-rows: auto minmax(0, 1fr); min-height: 100%; }
.copilot-intro { display: flex; align-items: flex-start; gap: 9px; padding: 8px 10px 7px; border-bottom: 1px solid var(--border-subtle); }
.copilot-mark { display: grid; place-items: center; width: 29px; height: 29px; border: 1px solid #4b403a; background: var(--accent-soft); color: var(--accent-strong); }
.copilot-title-row { display: flex; align-items: center; gap: 9px; }
