+.evidence-list h3 { margin: 0 0 5px; color: var(--text-muted); font-size: 9px; text-transform: uppercase; }
+.evidence-list ul { margin: 0; padding-left: 15px; color: var(--text-faint); font-size: 8.5px; line-height: 1.5; }
+.credibility-panel { grid-column: 1 / 5; border-top: 1px solid var(--border); }
+.credibility-panel header { display: flex; align-items: center; justify-content: space-between; min-height: 39px; padding: 6px 10px; border-bottom: 1px solid var(--border); }
+.credibility-panel h3 { margin: 2px 0 0; font-size: 10.5px; }
+.credibility-panel header small { color: var(--text-faint); font-size: 8.5px; }
+.credibility-panel table { width: 100%; border-collapse: collapse; }
+.credibility-panel th,
+.credibility-panel td { min-height: 25px; padding: 5px 9px; border-bottom: 1px solid var(--border-subtle); text-align: left; font-size: 8.5px; }
+.credibility-panel th { color: var(--text-faint); text-transform: uppercase; }
+.credibility-panel td:nth-child(2) { color: var(--text); font-family: var(--font-mono); }
+.credibility-panel td:nth-child(3) { color: var(--text-faint); }
+.regime-tags { display: flex; flex-wrap: wrap; gap: 5px; padding: 7px 9px; }
+.regime-tags span { padding: 2px 6px; border: 1px solid var(--border); color: var(--text-faint); font-family: var(--font-mono); font-size: 8px; text-transform: uppercase; }
+.regime-tags .validated { border-color: #436951; color: var(--green); }
+.regime-tags .extrapolated { border-color: #6b5936; color: var(--yellow); }
